import path from 'node:path';import {setupPromotion} from './promotion-preview.js';
export async function setupPeriods(page){
 await setupPromotion(page);await page.evaluate(()=>{const schoolId='school@preview.test',k='orbit.school.academics.demo.v1:'+encodeURIComponent(schoolId),A=JSON.parse(localStorage.getItem(k));A.teachers=[1,2,3].map(n=>({id:'t'+n,schoolId,name:'Teacher '+n+' · المعلم '+n,teacherCode:'T'+n}));A.subjects=[{id:'math',schoolId,name:'Mathematics · الرياضيات',status:'active'},{id:'science',schoolId,name:'Science · العلوم',status:'active'},{id:'art',schoolId,name:'Art · الفنون',status:'active'}];A.allocations=[];A.revision++;localStorage.setItem(k,JSON.stringify(A));const R=JSON.parse(localStorage.getItem('orbit.recruitment.v1'));R.accounts.push(...[1,2,3].map(n=>({email:'teacher'+n+'@period.test',role:'teacher',status:'active',name:'Teacher '+n})),{email:'student4@period.test',role:'student',status:'active',name:'Student Four'});localStorage.setItem('orbit.recruitment.v1',JSON.stringify(R));localStorage.setItem('orbit.school.education.links.v1:'+encodeURIComponent(schoolId),JSON.stringify({schema:1,schoolId,revision:0,links:[],mappings:[1,2,3].map(n=>({id:'teacher-map-'+n,schoolId,role:'teachers',academicId:'t'+n,accountId:'teacher'+n+'@period.test'}))}));});
 for(const f of ['profiles.js','recruitment-service.js','school-year-context.js','school-section-service.js','school-teaching-service.js','school-period-service.js'])await page.addScriptTag({path:path.resolve('shared',f)});
 await page.evaluate(()=>{window.B=OrbitSchoolPeriods;window.bc=()=>B.read('source').context;window.bt=f=>{try{return f();}catch(e){return e.message;}};const S=OrbitSchoolSections,T=OrbitSchoolTeaching;window.sec={};const a=S.save('',{academicYearId:'source',gradeName:'10',name:'C'},S.read().context);sec.a=a.id;sec.grade=a.gradeId;sec.b=S.save('',{academicYearId:'source',gradeId:a.gradeId,name:'D'},S.read().context).id;sec.future=S.save('',{academicYearId:'target',gradeId:a.gradeId,name:'C'},S.read().context).id;window.assign={};for(const [tag,sectionId,yearId]of [['a',sec.a,'source'],['b',sec.b,'source'],['future',sec.future,'target']])for(const [subjectId,teacherId]of [['math',tag==='b'?'t2':'t1'],['science',tag==='b'?'t1':'t2']]){assign[tag+subjectId]=T.save('',{academicYearId:yearId,teacherId,subjectId,gradeId:a.gradeId,sectionId},T.read(yearId).context,true).id;}B.setRequirements('source',a.gradeId,[{subjectId:'math',count:2},{subjectId:'science',count:1},{subjectId:'art',count:0}],bc(),true);B.setRequirements('target',a.gradeId,[{subjectId:'math',count:2},{subjectId:'science',count:1},{subjectId:'art',count:0}],B.read('target').context,true);window.fill=(sectionId=sec.a,yearId='source')=>B.applySuggestion(yearId,[sectionId],B.read(yearId).context,false,true);window.pub=(sectionIds=[sec.a],yearId='source')=>B.publish(yearId,sectionIds,B.read(yearId).context,true);});
}
